using System.Security.Cryptography;
using System.Text;
using Npgsql;

namespace Taranom.OrgScope.Foundation;

internal sealed record ScopedDraftAudit(string ScopeRef, string ItemRef,
    string SourceRef, int EventNo, string EventType, string EventSha256);

// Audit is generated by a PostgreSQL AFTER INSERT trigger, never by an
// application role. Every exposed row is verified against the original draft
// and a separately recomputed hash. Missing/mismatched audit fails closed.
internal static class OrgDraftAuditVerifier
{
    internal static async Task<ScopedDraftAudit?> VerifyAsync(
        NpgsqlConnection conn, NpgsqlTransaction? tx, string scope,
        string itemRef, CancellationToken ct = default)
    {
        await using var cmd = new NpgsqlCommand("""
            SELECT d.source_ref,a.source_ref,a.event_no,a.event_type,
                   a.event_sha256
            FROM public.internal_test_org_draft_item d
            LEFT JOIN public.internal_test_org_draft_audit a
              ON a.scope_ref=d.scope_ref AND a.item_ref=d.item_ref
              AND a.event_no=1
            WHERE d.scope_ref=@scope AND d.item_ref=@item
            """, conn, tx);
        cmd.Parameters.AddWithValue("scope",scope);
        cmd.Parameters.AddWithValue("item",itemRef);
        await using var row = await cmd.ExecuteReaderAsync(ct);
        if (!await row.ReadAsync(ct)) return null;
        if (row.IsDBNull(1) || row.IsDBNull(2) || row.IsDBNull(3) ||
            row.IsDBNull(4))
            throw new InvalidOperationException("ORG_DRAFT_MISSING_AUDIT");
        var original = row.GetString(0);
        var auditedSource = row.GetString(1);
        var ordinal = row.GetInt32(2);
        var eventType = row.GetString(3);
        var hash = row.GetString(4);
        var preimage = "TRN-TECH-133|" + scope + "|" + itemRef + "|" +
            original + "|DRAFT_RECORDED_TEST_ONLY|1";
        var expected = Convert.ToHexString(
            SHA256.HashData(Encoding.UTF8.GetBytes(preimage)));
        if (ordinal != 1 || eventType != OrgDraftAuditSchema.EventType ||
            original != auditedSource ||
            !string.Equals(hash,expected,StringComparison.Ordinal))
            throw new InvalidOperationException("ORG_DRAFT_AUDIT_INTEGRITY_MISMATCH");
        if (await row.ReadAsync(ct))
            throw new InvalidOperationException("ORG_DRAFT_DUPLICATE_AUDIT");
        return new ScopedDraftAudit(scope,itemRef,original,ordinal,
            eventType,hash);
    }
}
